    /**
     * Tests getting all CustomerAddresss.
     *
     * @return    Collection
     */
    public List<CustomerAddress> testGetAll() throws Throwable {
    LOGGER.info( "CustomerAddressTest:testGetAll() - Retrieving Collection of CustomerAddresss:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all CustomerAddress : " );
    List<CustomerAddress> collection  = null;

    try {
        // call the static get method on the CustomerAddressService
        collection = service.getAllCustomerAddress();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            CustomerAddress currEntity  = null;
            Iterator<CustomerAddress> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCustomerAddressId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

